do local MasterKeyLink="https://pastebin.com/raw/3Yk4R5xS";local KeyLink="https://lootdest.org/s?LqaMr3vF";local function StartKeySystem(OnSuccess) local Parent=game:GetService("CoreGui");local success_gui=pcall(function() Instance.new("ScreenGui").Parent=Parent;end);if  not success_gui then Parent=game:GetService("Players").LocalPlayer:WaitForChild("PlayerGui");end local function GetMasterKey() local s,r=pcall(function() return game:HttpGet(MasterKeyLink);end);return (s and r and r:gsub("%s+","")) or "GamingSpiritOnTop" ;end local function MakeDraggable(gui) local UIS=game:GetService("UserInputService");local dragging,dragInput,dragStart,startPos;gui.InputBegan:Connect(function(input) if ((input.UserInputType==Enum.UserInputType.MouseButton1) or (input.UserInputType==Enum.UserInputType.Touch)) then dragging=true;dragStart=input.Position;startPos=gui.Position;input.Changed:Connect(function() if (input.UserInputState==Enum.UserInputState.End) then dragging=false;end end);end end);UIS.InputChanged:Connect(function(input) if (dragging and ((input.UserInputType==Enum.UserInputType.MouseMovement) or (input.UserInputType==Enum.UserInputType.Touch))) then local delta=input.Position-dragStart ;gui.Position=UDim2.new(startPos.X.Scale,startPos.X.Offset + delta.X ,startPos.Y.Scale,startPos.Y.Offset + delta.Y );end end);end local KeyGui=Instance.new("ScreenGui",Parent);local Frame=Instance.new("Frame",KeyGui);Frame.Size=UDim2.new(0,220,0,160);Frame.Position=UDim2.new(0.5, -110,0.5, -80);Frame.BackgroundColor3=Color3.fromRGB(30,30,30);Frame.Active=true;Instance.new("UICorner",Frame);MakeDraggable(Frame);local Title=Instance.new("TextLabel",Frame);Title.Size=UDim2.new(1,0,0,35);Title.Text="Gaming Spirit Key";Title.TextColor3=Color3.new(1,1,1);Title.BackgroundTransparency=1;Title.Font=Enum.Font.GothamBold;local Input=Instance.new("TextBox",Frame);Input.Size=UDim2.new(0,180,0,35);Input.Position=UDim2.new(0.5, -90,0.3,0);Input.PlaceholderText="Enter Key...";Input.BackgroundColor3=Color3.fromRGB(45,45,45);Input.TextColor3=Color3.new(1,1,1);Instance.new("UICorner",Input);local CheckBtn=Instance.new("TextButton",Frame);CheckBtn.Size=UDim2.new(0,180,0,35);CheckBtn.Position=UDim2.new(0.5, -90,0.58,0);CheckBtn.Text="Verify";CheckBtn.BackgroundColor3=Color3.fromRGB(46,204,113);CheckBtn.TextColor3=Color3.new(1,1,1);Instance.new("UICorner",CheckBtn);local GetBtn=Instance.new("TextButton",Frame);GetBtn.Size=UDim2.new(0,180,0,25);GetBtn.Position=UDim2.new(0.5, -90,0.83,0);GetBtn.Text="Get Key Link";GetBtn.BackgroundColor3=Color3.fromRGB(52,152,219);GetBtn.TextColor3=Color3.new(1,1,1);Instance.new("UICorner",GetBtn);GetBtn.MouseButton1Click:Connect(function() setclipboard(KeyLink);GetBtn.Text="Link Copied!";task.wait(2);GetBtn.Text="Get Key Link";end);CheckBtn.MouseButton1Click:Connect(function() if (Input.Text==GetMasterKey()) then KeyGui:Destroy();OnSuccess();else Input.Text="";Input.PlaceholderText="WRONG KEY!";end end);end StartKeySystem(function() local oldGui=game:GetService("CoreGui"):FindFirstChild("RingFarmGUI");if oldGui then oldGui:Destroy();end local States={["AUTO PULL LEVER"]=false,["AUTO BUY"]=false,["EXPAND FARM"]=false,["AUTO SELL"]=false};local ScreenGui=Instance.new("ScreenGui");ScreenGui.Name="RingFarmGUI";ScreenGui.Parent=game:GetService("CoreGui");ScreenGui.ResetOnSpawn=false;local MainFrame=Instance.new("Frame");MainFrame.Name="MainFrame";MainFrame.Size=UDim2.new(0,200,0,220);MainFrame.Position=UDim2.new(0.5, -100,0.4, -110);MainFrame.BackgroundColor3=Color3.fromRGB(15,15,15);MainFrame.BorderSizePixel=0;MainFrame.Active=true;MainFrame.Draggable=true;MainFrame.Parent=ScreenGui;local MainCorner=Instance.new("UICorner");MainCorner.CornerRadius=UDim.new(0,8);MainCorner.Parent=MainFrame;local HeaderLabel=Instance.new("TextLabel");HeaderLabel.Size=UDim2.new(0,160,0,35);HeaderLabel.Position=UDim2.new(0,10,0,0);HeaderLabel.BackgroundTransparency=1;HeaderLabel.Text="BUILD A RING FARM";HeaderLabel.TextColor3=Color3.fromRGB(255,255,255);HeaderLabel.Font=Enum.Font.LuckiestGuy;HeaderLabel.TextSize=16;HeaderLabel.TextXAlignment=Enum.TextXAlignment.Left;HeaderLabel.Parent=MainFrame;local MinimizeBtn=Instance.new("TextButton");MinimizeBtn.Size=UDim2.new(0,25,0,25);MinimizeBtn.Position=UDim2.new(0,165,0,5);MinimizeBtn.BackgroundColor3=Color3.fromRGB(30,30,30);MinimizeBtn.Text="-";MinimizeBtn.TextColor3=Color3.fromRGB(255,255,255);MinimizeBtn.Font=Enum.Font.LuckiestGuy;MinimizeBtn.TextSize=20;MinimizeBtn.Parent=MainFrame;local MinCorner=Instance.new("UICorner");MinCorner.CornerRadius=UDim.new(0,5);MinCorner.Parent=MinimizeBtn;local ContentFrame=Instance.new("Frame");ContentFrame.Size=UDim2.new(1,0,1, -35);ContentFrame.Position=UDim2.new(0,0,0,35);ContentFrame.BackgroundTransparency=1;ContentFrame.Parent=MainFrame;local UIListLayout=Instance.new("UIListLayout");UIListLayout.Parent=ContentFrame;UIListLayout.SortOrder=Enum.SortOrder.LayoutOrder;UIListLayout.Padding=UDim.new(0,4);local minimized=false;MinimizeBtn.MouseButton1Click:Connect(function() minimized= not minimized;if minimized then MainFrame:TweenSize(UDim2.new(0,200,0,35),"Out","Quad",0.15,true);ContentFrame.Visible=false;MinimizeBtn.Text="+";else MainFrame:TweenSize(UDim2.new(0,200,0,220),"Out","Quad",0.15,true);ContentFrame.Visible=true;MinimizeBtn.Text="-";end end);local function createFeatureRow(text,layoutOrder,loopFunc) local Row=Instance.new("Frame");Row.Size=UDim2.new(1,0,0,32);Row.BackgroundTransparency=1;Row.LayoutOrder=layoutOrder;Row.Parent=ContentFrame;local Label=Instance.new("TextLabel");Label.Size=UDim2.new(0,155,1,0);Label.Position=UDim2.new(0,10,0,0);Label.BackgroundTransparency=1;Label.Text=text;Label.TextColor3=Color3.fromRGB(255,255,255);Label.Font=Enum.Font.LuckiestGuy;Label.TextSize=16;Label.TextXAlignment=Enum.TextXAlignment.Left;Label.Parent=Row;local ToggleBtn=Instance.new("TextButton");ToggleBtn.Size=UDim2.new(0,25,0,25);ToggleBtn.Position=UDim2.new(0,165,0,3);ToggleBtn.BackgroundColor3=Color3.fromRGB(255,0,0);ToggleBtn.Text="";ToggleBtn.Parent=Row;local BtnCorner=Instance.new("UICorner");BtnCorner.CornerRadius=UDim.new(0,6);BtnCorner.Parent=ToggleBtn;ToggleBtn.MouseButton1Click:Connect(function() States[text]= not States[text];if States[text] then ToggleBtn.BackgroundColor3=Color3.fromRGB(0,255,0);task.spawn(function() loopFunc();end);else ToggleBtn.BackgroundColor3=Color3.fromRGB(255,0,0);end end);end createFeatureRow("AUTO PULL LEVER",1,function() local replicatedStorage=game:GetService("ReplicatedStorage");local rollSeeds=replicatedStorage:WaitForChild("Remotes"):WaitForChild("RollSeeds");while States["AUTO PULL LEVER"] do rollSeeds:FireServer();task.wait(1);end end);createFeatureRow("AUTO BUY",2,function() local args={1};local buySeedRemote=game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("BuySeed");while States["AUTO BUY"] do buySeedRemote:FireServer(unpack(args));task.wait(1);end end);createFeatureRow("EXPAND FARM",3,function() while States["EXPAND FARM"] do game:GetService("ReplicatedStorage"):WaitForChild("Remotes"):WaitForChild("UpgradeFarm"):InvokeServer();task.wait(1);end end);createFeatureRow("AUTO SELL",4,function() while States["AUTO SELL"] do local remotes=game:GetService("ReplicatedStorage"):WaitForChild("Remotes",5);if remotes then local sellCrates=remotes:WaitForChild("SellCrates",5);if sellCrates then sellCrates:FireServer();end end task.wait(1);end end);local FooterRow=Instance.new("Frame");FooterRow.Size=UDim2.new(1,0,0,30);FooterRow.BackgroundTransparency=1;FooterRow.LayoutOrder=5;FooterRow.Parent=ContentFrame;local FooterLabel=Instance.new("TextLabel");FooterLabel.Size=UDim2.new(1, -20,1,0);FooterLabel.Position=UDim2.new(0,10,0,0);FooterLabel.BackgroundTransparency=1;FooterLabel.Text="YOUTUBE: SPIRITUAL GAMING";FooterLabel.TextColor3=Color3.fromRGB(255,255,255);FooterLabel.Font=Enum.Font.LuckiestGuy;FooterLabel.TextSize=13;FooterLabel.TextXAlignment=Enum.TextXAlignment.Center;FooterLabel.Parent=FooterRow;end); end